/// <summary>
/// Displays the rendered label preview for a label layout. Opened by
/// <c>AAXWHSLabelPreviewController</c> with an <c>AAXWHSLabelPreviewContext</c> as the caller object,
/// and supports paging, rotation, download, seed record selection, size override, and editing and
/// saving the source ZPL.
/// </summary>
[Form]
public class AAXWHSLabelPreviewDialog extends FormRun
{
    AAXWHSLabelPreviewContext   context;
    List                        pngs;           // One original PNG container per label block
    int                         currentIndex;   // 1-based page index
    str                         currentUrl;     // Temp store URL of the displayed page
    Map                         pageUrls;       // Temp store URL cache keyed by page and turns

    // Cumulative clockwise quarter turns per page
    Map                         pageTurns;      // Integer -> Integer

    // Identity used to re-render through AAXWHSLabelPreviewController::buildContext
    TableId                     layoutTableId;
    RecId                       layoutRecId;
    TableId                     seedTableId;
    RecId                       selectedSeedRecId;  // 0 resolves the most recent record

    // Whether the source ZPL of this layout type can be saved
    boolean                     canSave;
}

/// <summary>
/// Initializes the form from the preview context passed by the caller and shows the first label page.
/// </summary>
public void init()
{
    super();

    context = element.args().parmObject() as AAXWHSLabelPreviewContext;
    if (!context)
    {
        return;
    }

    element.initFromContext(context);
}

/// <summary>
/// Initializes all form state from a preview context and shows the first page. Clears the
/// rotation state and URL cache so the new render starts upright.
/// </summary>
/// <param name = "_context">The preview context to bind.</param>
public void initFromContext(AAXWHSLabelPreviewContext _context)
{
    context = _context;
    pngs    = context.parmPngList();

    // Clear the URL cache and rotation state for the new render
    pageUrls  = new Map(Types::String, Types::String);   // key "page|turns" -> URL
    pageTurns = new Map(Types::Integer, Types::Integer);  // page -> cumulative turns (0..3)

    // Identity used to re-render and the selected seed record
    layoutTableId     = context.parmLayoutTableId();
    layoutRecId       = context.parmLayoutRecId();
    seedTableId       = context.parmSeedTableId();
    selectedSeedRecId = context.parmSeedRecId();

    // Badge showing whether a live record or sample data was used
    BadgeText.text(context.parmBadgeText());

    // The editable source ZPL with its tokens and template blocks
    SourceZplText.text(context.parmSourceZpl());

    // The read-only translated ZPL that was rendered
    ZplText.text(context.parmFinalZpl());

    // Saving is only offered for layout types that can be written back
    canSave = context.parmCanSave();
    SourceZplText.allowEdit(canSave);
    SaveButton.enabled(canSave);
    SaveButton.visible(canSave);

    // Show the seed table and the natural identifier of the selected record
    SeedTableLabel.text(context.parmSeedTableLabel());
    SeedRecordEdit.text(element.seedRecordIdentifierText(selectedSeedRecId));

    // Repopulate the size override from the context, falling back to the displayed defaults
    boolean overrideOn = context.parmOverrideSize();
    OverrideSizeCheck.value(overrideOn);
    SizeWidthIn.realValue(context.parmOverrideWidthIn()  > 0 ? context.parmOverrideWidthIn()  : 4);
    SizeHeightIn.realValue(context.parmOverrideHeightIn() > 0 ? context.parmOverrideHeightIn() : 6);
    SizeDpi.value(context.parmOverrideDpi() > 0 ? context.parmOverrideDpi() : 203);
    element.applySizeControlsEnabled(overrideOn);

    currentIndex = 1;
    element.showPage(currentIndex);
}

/// <summary>
/// Displays the requested label page and updates the pager and navigation buttons.
/// </summary>
/// <param name = "_page">The 1-based page to display.</param>
public void showPage(int _page)
{
    int total = pngs ? pngs.elements() : 0;
    if (total == 0)
    {
        return;
    }

    if (_page < 1)
    {
        _page = 1;
    }
    else if (_page > total)
    {
        _page = total;
    }

    currentIndex = _page;
    currentUrl   = this.urlForPage(_page);

    // Bind the image control to the temp store URL of the page
    PreviewImage.imageLocation(SysImageLocation::URL);
    PreviewImage.normalImage(currentUrl);

    PagerText.text(strFmt("@AAXWarehouseTools:LabelNofM", _page, total));

    // Paging is only relevant for multi-label ZPL
    PrevPageButton.visible(total > 1);
    NextPageButton.visible(total > 1);
    PrevPageButton.enabled(_page > 1);
    NextPageButton.enabled(_page < total);
}

/// <summary>
/// Returns the temp store URL for a label page at its current rotation, uploading the PNG on
/// first request.
/// </summary>
/// <param name = "_page">The 1-based page.</param>
/// <returns>The temp store URL for the page, or an empty string when the page has no PNG.</returns>
private str urlForPage(int _page)
{
    int turns = this.turnsForPage(_page);

    // Cache per page and rotation so a rotated page never reuses the upright URL
    str cacheKey = strFmt('%1|%2', _page, turns);

    if (pageUrls.exists(cacheKey))
    {
        str cached = pageUrls.lookup(cacheKey);
        if (cached)
        {
            return cached;
        }
    }

    // Walk to the original container for the page
    ListEnumerator listEnumerator = pngs.getEnumerator();
    int idx = 0;
    container pngContainer = conNull();
    while (listEnumerator.moveNext())
    {
        idx++;
        if (idx == _page)
        {
            pngContainer = listEnumerator.current();
            break;
        }
    }

    str url = '';
    if (conLen(pngContainer) > 0)
    {
        // Rotate from the original container by the cumulative turn count
        container displayContainer = (turns == 0)
            ? pngContainer
            : AAXZplRenderService::rotatePng(pngContainer, turns);

        // Upload the PNG to the temp store with a unique name per page and rotation
        System.IO.MemoryStream stream = AAXZplRenderService::pngContainerToStream(displayContainer);
        if (stream)
        {
            url = File::SendFileToTempStore(stream, strFmt('LabelPreview_%1_%2.png', _page, turns));
        }
    }

    pageUrls.insert(cacheKey, url);
    return url;
}

/// <summary>
/// Returns the cumulative clockwise quarter turns currently applied to a page.
/// </summary>
/// <param name = "_page">The 1-based page.</param>
/// <returns>The rotation of the page in quarter turns, from 0 to 3.</returns>
private int turnsForPage(int _page)
{
    if (pageTurns && pageTurns.exists(_page))
    {
        return pageTurns.lookup(_page);
    }

    return 0;
}

/// <summary>
/// Rotates the current page 90 degrees clockwise and redisplays it. Rotation is tracked per
/// page and always applied from the original image.
/// </summary>
public void rotateCurrentPage()
{
    int turns = this.turnsForPage(currentIndex);
    turns = (turns + 1) mod 4;
    pageTurns.insert(currentIndex, turns);

    // Redisplay the page at its new rotation
    element.showPage(currentIndex);
}

/// <summary>
/// Opens the current page's PNG in the browser so the user can download it.
/// </summary>
public void downloadCurrentPage()
{
    // Download the displayed image so the active rotation is honored
    if (currentUrl)
    {
        new Browser().navigate(currentUrl, false, false);
    }
}

/// <summary>
/// Re-renders the preview for the record chosen in the data source selector and
/// re-initializes the form state.
/// </summary>
public void refreshPreview()
{
    AAXWHSLabelPreviewContext   newContext;
    Common                      layoutRecord;
    container                   sizeArgs = element.sizeOverrideArgs();

    layoutRecord = element.rereadLayoutRecord();
    if (layoutRecord.RecId == 0)
    {
        return;
    }

    // Re-render against the selected seed record with the current size override
    newContext = AAXWHSLabelPreviewController::buildContext(
        layoutRecord, seedTableId, selectedSeedRecId,
        conPeek(sizeArgs, 1), conPeek(sizeArgs, 2), conPeek(sizeArgs, 3));
    if (!newContext)
    {
        // A validation gate has already reported the reason
        return;
    }

    element.initFromContext(newContext);
}

/// <summary>
/// Re-reads the originating layout record so the refresh, preview, and save actions operate
/// on a fresh buffer.
/// </summary>
/// <returns>The layout record, or a buffer with RecId 0 when it cannot be read.</returns>
private Common rereadLayoutRecord()
{
    Common      layoutRecord;
    DictTable   layoutDictTable;

    if (!layoutTableId || !layoutRecId)
    {
        return layoutRecord;
    }

    // Select the record by RecId through its runtime table
    layoutDictTable = new DictTable(layoutTableId);
    layoutRecord    = layoutDictTable.makeRecord();

    select firstonly layoutRecord
        where layoutRecord.RecId == layoutRecId;

    return layoutRecord;
}

/// <summary>
/// Re-renders the preview from the edited source ZPL without saving it. The edited text is
/// translated and rendered against the current seed record.
/// </summary>
public void previewEdits()
{
    AAXWHSLabelPreviewContext   newContext;
    Common                      layoutRecord;
    str                         editedSource = SourceZplText.text();
    container                   sizeArgs = element.sizeOverrideArgs();

    if (!editedSource)
    {
        // Nothing to preview
        return;
    }

    layoutRecord = element.rereadLayoutRecord();
    if (layoutRecord.RecId == 0)
    {
        return;
    }

    // Render the unsaved source with the current size override
    newContext = AAXWHSLabelPreviewController::renderFromSource(
        layoutRecord, editedSource, seedTableId, selectedSeedRecId,
        conPeek(sizeArgs, 1), conPeek(sizeArgs, 2), conPeek(sizeArgs, 3));

    if (!newContext)
    {
        // The layout type cannot be previewed and the reason has already been reported
        return;
    }

    element.initFromContext(newContext);
}

/// <summary>
/// Saves the edited source ZPL back to the layout and re-renders the preview from the saved
/// state. The controller performs the security check and returns the message to display.
/// </summary>
public void saveSource()
{
    str editedSource = SourceZplText.text();
    container result;
    boolean saved;
    str message;

    if (!canSave)
    {
        return;
    }

    if (!editedSource)
    {
        // Never persist an empty source
        info("@AAXWarehouseTools:SaveEmptySource");
        return;
    }

    // The result holds the success flag and the message to display
    result  = AAXWHSLabelPreviewController::saveSourceToLayout(layoutTableId, layoutRecId, editedSource);
    saved   = conPeek(result, 1);
    message = conPeek(result, 2);

    if (message)
    {
        info(message);
    }

    // Re-render from the saved layout
    if (saved)
    {
        element.refreshPreview();
    }
}

/// <summary>
/// Returns the field that identifies a seed record to the user, using the title field of the
/// seed table and falling back to RecId.
/// </summary>
/// <returns>The identifier field id, or the RecId field id when the table has no title field.</returns>
private FieldId seedIdentifierFieldId()
{
    SysDictTable    dictTable;
    FieldId         titleFieldId;

    if (!seedTableId)
    {
        return fieldNum(Common, RecId);
    }

    dictTable    = SysDictTable::newTableId(seedTableId);
    titleFieldId = dictTable ? dictTable.titleField1() : 0;

    return titleFieldId ? titleFieldId : fieldNum(Common, RecId);
}

/// <summary>
/// Resolves the identifier text from the seed selector to a record id by matching the
/// identifier field of the seed table, most recent first.
/// </summary>
/// <param name = "_identifierText">The selector text, or an empty string.</param>
/// <returns>The matching record id, or 0 when there is no match.</returns>
private RecId resolveSeedRecIdFromIdentifier(str _identifierText)
{
    FieldId                 idFieldId;
    Query                   query;
    QueryBuildDataSource    qbds;
    QueryRun                queryRun;

    if (!_identifierText || !seedTableId)
    {
        return 0;
    }

    idFieldId = element.seedIdentifierFieldId();

    // Without a natural identifier the text is the record id
    if (idFieldId == fieldNum(Common, RecId))
    {
        return str2int64(_identifierText);
    }

    query = new Query();
    qbds  = query.addDataSource(seedTableId);
    qbds.addRange(idFieldId).value(queryValue(_identifierText));
    qbds.addSortField(fieldNum(Common, RecId), SortOrder::Descending);

    queryRun = new QueryRun(query);
    if (queryRun.next())
    {
        return queryRun.getNo(1).RecId;
    }

    return 0;
}

/// <summary>
/// Returns the identifier text displayed in the seed selector for a record.
/// </summary>
/// <param name = "_seedRecId">The record id of the selected seed record, or 0 for none.</param>
/// <returns>The identifier value of the record, or an empty string.</returns>
private str seedRecordIdentifierText(RecId _seedRecId)
{
    FieldId idFieldId;
    Common  seedBuffer;

    if (!_seedRecId || !seedTableId)
    {
        return '';
    }

    idFieldId = element.seedIdentifierFieldId();

    if (idFieldId == fieldNum(Common, RecId))
    {
        return int642str(_seedRecId);
    }

    seedBuffer = new DictTable(seedTableId).makeRecord();
    select firstonly seedBuffer
        where seedBuffer.RecId == _seedRecId;

    return seedBuffer.RecId ? any2Str(seedBuffer.(idFieldId)) : '';
}

/// <summary>
/// Stores the seed record chosen in the data source selector by resolving its identifier text
/// to a record id. An empty or unmatched value selects the most recent record on the next refresh.
/// </summary>
/// <param name = "_identifierText">The selector text, or an empty string.</param>
public void setSelectedSeedRecId(str _identifierText)
{
    selectedSeedRecId = element.resolveSeedRecIdFromIdentifier(_identifierText);
}

/// <summary>
/// Enables or disables the width, height, and DPI inputs to match the size override check box.
/// </summary>
/// <param name = "_enabled">True when the override is on.</param>
public void applySizeControlsEnabled(boolean _enabled)
{
    SizeWidthIn.enabled(_enabled);
    SizeHeightIn.enabled(_enabled);
    SizeDpi.enabled(_enabled);
}

/// <summary>
/// Builds the size override arguments for the render calls from the label size group.
/// </summary>
/// <returns>
/// A container of width in millimeters, height in millimeters, and dots per millimeter; all
/// zero when the override is off.
/// </returns>
private container sizeOverrideArgs()
{
    real widthMm  = 0;
    real heightMm = 0;
    int  dpmm     = 0;

    // Honor the override only when both dimensions are positive
    if (OverrideSizeCheck.value() && SizeWidthIn.realValue() > 0 && SizeHeightIn.realValue() > 0)
    {
        widthMm  = SizeWidthIn.realValue()  * 25.4;   // inches -> mm
        heightMm = SizeHeightIn.realValue() * 25.4;   // inches -> mm

        // Zero defers to the configured density default
        if (SizeDpi.value() > 0)
        {
            dpmm = real2int(round(SizeDpi.value() / 25.4, 1.0));
        }
    }

    return [widthMm, heightMm, dpmm];
}

/// <summary>
/// Runs a lookup over the seed table for the data source selector, returning the natural
/// identifier of the chosen record.
/// </summary>
/// <param name = "_control">The selector control the lookup is attached to.</param>
public void lookupSeedRecord(FormStringControl _control)
{
    const FieldId RecIdFieldId = 65534; // Platform RecId FieldId.

    if (!seedTableId)
    {
        return;
    }

    SysTableLookup          sysTableLookup = SysTableLookup::newParameters(seedTableId, _control);
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(seedTableId);
    SysDictTable            dictTable = SysDictTable::newTableId(seedTableId);
    FieldId                 idFieldId = element.seedIdentifierFieldId();
    FieldId                 titleField2Id = dictTable ? dictTable.titleField2() : 0;

    // Most recent first
    qbds.addSortField(RecIdFieldId, SortOrder::Descending);

    // Return the natural identifier rather than the record id
    sysTableLookup.addLookupfield(idFieldId);

    // Show the second title field as extra context when it differs
    if (titleField2Id && titleField2Id != idFieldId)
    {
        sysTableLookup.addLookupField(titleField2Id);
    }

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

/// <summary>
/// Navigates to the previous label page.
/// </summary>
public void clicked()
{
    super();
    element.showPage(currentIndex - 1);
}

/// <summary>
/// Navigates to the next label page.
/// </summary>
public void clicked()
{
    super();
    element.showPage(currentIndex + 1);
}

/// <summary>
/// Downloads the currently displayed PNG.
/// </summary>
public void clicked()
{
    super();
    element.downloadCurrentPage();
}

/// <summary>
/// Rotates the current page 90 degrees clockwise.
/// </summary>
public void clicked()
{
    super();
    element.rotateCurrentPage();
}

/// <summary>
/// Re-renders the preview from the edited source ZPL without saving it.
/// </summary>
public void clicked()
{
    super();
    element.previewEdits();
}

/// <summary>
/// Saves the edited source ZPL back to the layout.
/// </summary>
public void clicked()
{
    super();
    element.saveSource();
}

/// <summary>
/// Opens the seed record lookup over the seed table.
/// </summary>
public void lookup()
{
    // The lookup form is driven by SysTableLookup, so super() is not called
    element.lookupSeedRecord(this);
}

/// <summary>
/// Stores the seed record identified by the control text.
/// </summary>
/// <returns>True if the control value was accepted.</returns>
public boolean modified()
{
    boolean ret = super();

    // An empty value selects the most recent record on the next refresh
    element.setSelectedSeedRecId(this.text());

    return ret;
}

/// <summary>
/// Re-renders the preview using the selected seed record.
/// </summary>
public void clicked()
{
    super();
    element.refreshPreview();
}

/// <summary>
/// Enables or disables the size inputs to follow the override check box. The preview is
/// re-rendered on the next refresh.
/// </summary>
public void clicked()
{
    super();
    element.applySizeControlsEnabled(this.value());
}
